#include "UnityPBSLighting.cginc"
// ===== PLANAR REFLECTION (begin) ===================================================================================
// The scene mirrored in the water (Scripts/World/WaterReflection.cs). While water is on screen a second camera renders
// everything but the water, grass and particles mirrored about one water level, at half resolution, without fog, with
// an oblique near plane on the water. It arrives as globals shared by every water material (so not Properties):
//   _WaterReflection        the mirrored scene (HDR, mipmapped), at the water pixel's own screen position;
//   _WaterReflectionDepth   its depth, and _WaterReflectionInvProj its inverse (oblique) GPU projection: how far the
//                           reflected light travelled, so the reflection gets the fog of its whole path back;
//   _WaterReflectionParams  x = the mirror level (m), y = 1 while live for this camera (0: sky probe only),
//                           z = intensity (dims at night like the sky probe), w = how much ripples bend it (0..1).
// surf hands the pixel's screen and world position to the lighting function (where the reflected ray is known in world
// space) through two statics: same pixel, same pass.
sampler2D _WaterReflection, _WaterReflectionDepth;
float4 _WaterReflectionParams;
float4x4 _WaterReflectionInvProj;
static float4 wrScreenPos;
static float3 wrWorldPos;
// 0..1 screen position of a world point (like screenPos.xy / w), and its clip w (<= 0 behind the camera).
float3 WaterScreen(float3 p)
{
    float4 s = ComputeScreenPos(mul(UNITY_MATRIX_VP, float4(p, 1)));
    return float3(s.xy / max(s.w, 1e-4), s.w);
}
// View depth (m) of what the reflection shows at uv, along the whole path (eye, water, the thing); -1 for open sky.
float WaterMirrorDepth(float2 uv)
{
    float raw = tex2Dlod(_WaterReflectionDepth, float4(uv, 0, 0)).r;
    #if UNITY_REVERSED_Z
    if (raw < 1e-6) return -1;
    #else
    if (raw > 1 - 1e-6) return -1;
    raw = raw * 2 - 1;
    #endif
    float4 v = mul(_WaterReflectionInvProj, float4(uv * 2 - 1, raw, 1));
    return -v.z / v.w;
}
// How clear the air is over view depth d (1 = no fog), as UNITY_APPLY_FOG has it; 1 with fog off.
float WaterFogFactor(float d)
{
    #if defined(FOG_LINEAR) || defined(FOG_EXP) || defined(FOG_EXP2)
    UNITY_CALC_FOG_FACTOR_RAW(d);
    return saturate(unityFogFactor);
    #else
    return 1;
    #endif
}
// The mirrored scene for the reflected ray r (world space, from the full ripple normal) and how much of the sky probe it
// replaces (alpha). Water at another level than the mirror's shifts its lookup by the difference and hands back to the
// sky probe beyond about a metre (sloping creeks, far ponds); so does a lookup bent off the screen.
half4 WaterPlanar(half3 r, half3 viewDir, half smoothness)
{
    if (_WaterReflectionParams.y < 0.5 || unity_OrthoParams.w > 0.5) return 0;
    float3 w = wrWorldPos;
    float eye = wrScreenPos.w;                                             // eye depth of this water pixel
    float3 lift = float3(0, 2 * (w.y - _WaterReflectionParams.x), 0);     // mirrored about another level: shift
    // How far past the water the reflected thing stands (open sky: far), from the unbent lookup.
    float seen = WaterMirrorDepth(WaterScreen(w - lift).xy);
    float beyond = seen < 0 ? 50 : clamp(seen - eye, 0.2, 50);
    // Ripples bend the reflected ray, but less than they tilt the light: at full strength they shatter the mirror.
    half3 r0 = half3(-viewDir.x, viewDir.y, -viewDir.z);                   // reflect(-viewDir, up)
    half3 rb = normalize(lerp(r0, r, _WaterReflectionParams.w));
    float3 s = WaterScreen(w + float3(rb.x, -rb.y, rb.z) * beyond - lift);
    float2 uv = s.xy;
    half off = max(max(-uv.x, uv.x - 1), max(-uv.y, uv.y - 1));          // > 0 off the screen
    half live = saturate(1 - off * 16) * step(0.01, s.z) * saturate((1.3 - abs(lift.y * 0.5)) / 0.8);
    half3 c = tex2Dlod(_WaterReflection, float4(uv, 0, saturate(1 - smoothness) * 4)).rgb;
    // Fog over the reflected leg (the surface's own fog covers eye to water): the thing is seen through its own haze.
    float d = WaterMirrorDepth(uv);
    if (d > eye) c = lerp(unity_FogColor.rgb, c, saturate(WaterFogFactor(d) / max(WaterFogFactor(eye), 1e-3)));
    return half4(c * _WaterReflectionParams.z, live);
}
// ===== PLANAR REFLECTION (end) =====================================================================================

half3 r = reflect(-viewDir, s.Normal);
// ===== PLANAR REFLECTION (begin): the mirrored scene replaces the sky probe where it has an answer (base pass only;
// the add pass has no indirect light). The fade under the horizon below stands in for the banks the sky probe cannot
// show, so it is lifted where the real banks are reflected. (r is used only for that fade after this point.)
#ifdef UNITY_PASS_FORWARDBASE
half4 planar = WaterPlanar(r, viewDir, s.Smoothness);
gi.indirect.specular = lerp(gi.indirect.specular, planar.rgb, planar.a);
r.y = lerp(r.y, 1, planar.a);
#endif
// ===== PLANAR REFLECTION (end)

o.Metallic = 0;
// ===== PLANAR REFLECTION (begin): this pixel's position, for WaterPlanar in LightingWater.
wrScreenPos = IN.screenPos; wrWorldPos = IN.worldPos;
// ===== PLANAR REFLECTION (end)

var waterMat = WaterMaterial();
// The scene mirrored in the water (WaterReflection). Registering a surface also puts it on the Water layer, which the
// reflection camera leaves out.
var mirror = art.waterSurface != null ? gameObject.AddComponent<WaterReflection>() : null;
Func<float, float, float> ground = (x, z) => HeightAt(x, z);

go.AddComponent<MeshFilter>().sharedMesh = Water.LakeMesh(k, ground);
var r = go.AddComponent<MeshRenderer>(); r.sharedMaterial = waterMat; r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off; r.receiveShadows = false;
