using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Rendering;

namespace Crulanda.World
{
    /// <summary>
    /// Planar reflections for the zone's water (built-in pipeline): ponds and creeks mirror their banks, trees, houses,
    /// bridges and the people beside them, not just the sky.
    /// - While water is in view, a second camera renders the scene mirrored about ONE water level into an HDR texture at
    ///   half the camera's resolution, just before the main camera culls (so it matches this frame's view exactly, capture
    ///   renders included). An oblique near plane sits on the water, so nothing under it is mirrored (beds, underwater banks,
    ///   wading legs, the mill wheel's lower paddles).
    /// - The level: the visible water nearest the camera (a lake's flat level; a creek's level at its point nearest the
    ///   camera), kept until another is clearly nearer. Water at another level shifts its lookup by the difference and hands
    ///   back to the sky probe beyond about a metre (Water.shader), so sloping creeks and far ponds never mirror wrongly.
    /// - Nothing is rendered while no water is in view, the nearest is further than <see cref="maxDistance"/>, or the camera
    ///   is at the water.
    /// - The reflection camera leaves out the water itself (the built-in Water layer), grass and particles (TransparentFX),
    ///   shadows, fog, MSAA and all but two pixel lights. The water shader puts the fog back for the whole path the reflected
    ///   light travels (eye to water to the thing), from the reflection's depth.
    /// - Night: dimmed with RenderSettings.reflectionIntensity like the sky probe (WorldClock); murky water reflects less
    ///   through its own _Reflect, so night water stays dark and Khaven's stays murky.
    /// - Other cameras (the zone map, the editor's scene view, probes) see the sky probe only.
    /// Shader side: Water.shader, PLANAR REFLECTION regions. No per-frame allocations (the texture is re-made only when the
    /// view size changes).
    /// </summary>
    public sealed class WaterReflection : MonoBehaviour
    {
        /// <summary>Water surfaces sit on Unity's built-in "Water" layer, which the reflection camera leaves out.</summary>
        public const int WaterLayer = 4;
        /// <summary>Unity's built-in "TransparentFX" layer: things never drawn in the reflection (grass, particles).</summary>
        public const int NoReflectLayer = 1;
        const int UILayer = 5;
        /// <summary>Off switch (for a graphics option): the water falls back to the sky probe.</summary>
        public static bool Enabled = true;

        [Tooltip("Reflection resolution as a fraction of the view's.")] public float scale = .5f;
        [Tooltip("Widest the reflection texture gets (pixels).")] public int maxWidth = 1024;
        [Tooltip("How much the ripples bend the reflection: 0 a perfect mirror, 1 as far as they tilt the light (shattered).")]
        [Range(0, 1)] public float bend = .25f;
        [Tooltip("Nothing lower than this above the water is mirrored (keeps the waterline clean), m.")] public float clipOffset = .05f;
        [Tooltip("No reflection is rendered while the nearest water in view is further than this, m.")] public float maxDistance = 120;

        struct Body { public Renderer renderer; public ZoneWater.Creek creek; public float level; }
        readonly List<Body> bodies = new List<Body>();
        readonly Plane[] frustum = new Plane[6];
        Camera mirror; RenderTexture target; int chosen = -1; bool rendering;
        static readonly int TextureId = Shader.PropertyToID("_WaterReflection"), DepthId = Shader.PropertyToID("_WaterReflectionDepth"),
            ParamsId = Shader.PropertyToID("_WaterReflectionParams"), InvProjId = Shader.PropertyToID("_WaterReflectionInvProj");

        /// <summary>Water surfaces registered (tests).</summary>
        public int Surfaces { get { return bodies.Count; } }
        /// <summary>True when the main camera's last frame drew a reflection; <see cref="Level"/> is the level it mirrored.</summary>
        public bool Live { get; private set; }
        public float Level { get; private set; }

        /// <summary>A creek surface chunk (its level is looked up along the creek).</summary>
        public void Add(Renderer surface, ZoneWater.Creek creek) { Register(surface, creek, 0); }
        /// <summary>A lake surface, flat at <paramref name="level"/>.</summary>
        public void Add(Renderer surface, float level) { Register(surface, null, level); }
        void Register(Renderer surface, ZoneWater.Creek creek, float level)
        {
            if (surface == null) return;
            surface.gameObject.layer = WaterLayer;
            bodies.Add(new Body { renderer = surface, creek = creek, level = level });
        }

        void OnEnable() { Camera.onPreCull += BeforeCull; }
        void OnDisable() { Camera.onPreCull -= BeforeCull; Live = false; Shader.SetGlobalVector(ParamsId, Vector4.zero); }
        void OnDestroy()
        {
            if (target != null) { target.Release(); Destroy(target); target = null; }
            if (mirror != null) Destroy(mirror.gameObject);
        }

        void BeforeCull(Camera cam)
        {
            if (rendering || cam == null || cam == mirror) return;
            if (cam != Camera.main) { Shader.SetGlobalVector(ParamsId, Vector4.zero); return; }   // map, scene view, probes: sky only
            Live = Enabled && SystemInfo.graphicsDeviceType != GraphicsDeviceType.Null && Pick(cam, out float level) && Draw(cam, level);
            if (!Live) Shader.SetGlobalVector(ParamsId, Vector4.zero);
        }

        /// <summary>The level to mirror: the visible water nearest the camera (the last choice stays unless another is clearly nearer).</summary>
        bool Pick(Camera cam, out float level)
        {
            level = 0;
            if (bodies.Count == 0 || cam.orthographic) return false;
            GeometryUtility.CalculateFrustumPlanes(cam, frustum);
            var eye = cam.transform.position;
            int best = -1; float bestSq = float.MaxValue, keptSq = -1;
            for (int i = 0; i < bodies.Count; i++)
            {
                var r = bodies[i].renderer;
                if (r == null || !r.enabled || !r.gameObject.activeInHierarchy) continue;
                var b = r.bounds;
                if (!GeometryUtility.TestPlanesAABB(frustum, b)) continue;
                float sq = b.SqrDistance(eye);
                if (i == chosen) keptSq = sq;
                if (sq < bestSq) { bestSq = sq; best = i; }
            }
            // Two waters about as near as each other don't swap the mirror back and forth every frame.
            if (best >= 0 && keptSq >= 0 && Mathf.Sqrt(keptSq) < Mathf.Sqrt(bestSq) * 1.25f + 2) { best = chosen; bestSq = keptSq; }
            chosen = best;
            if (best < 0 || bestSq > maxDistance * maxDistance) return false;
            var body = bodies[best];
            level = body.level;
            if (body.creek != null)
            {
                var near = body.renderer.bounds.ClosestPoint(eye);
                ZoneWater.Project(body.creek, new Vector2(near.x, near.z), out _, out level, out _);
            }
            return eye.y > level + clipOffset + .05f;   // at or under the water there is nothing to mirror
        }

        /// <summary>Renders the scene mirrored about y = level and hands it to the water shader.</summary>
        bool Draw(Camera cam, float level)
        {
            if (!Prepare(cam)) return false;
            var flip = Matrix4x4.identity; flip.m11 = -1; flip.m13 = 2 * level;   // mirror about y = level
            mirror.clearFlags = cam.clearFlags; mirror.backgroundColor = cam.backgroundColor;
            mirror.fieldOfView = cam.fieldOfView; mirror.nearClipPlane = cam.nearClipPlane; mirror.farClipPlane = cam.farClipPlane;
            mirror.cullingMask = cam.cullingMask & ~((1 << WaterLayer) | (1 << NoReflectLayer) | (1 << UILayer));
            // The mirrored eye (fog-free lighting, specular and sorting are worked out from it).
            var e = cam.transform.eulerAngles;
            mirror.transform.SetPositionAndRotation(flip.MultiplyPoint(cam.transform.position), Quaternion.Euler(-e.x, e.y, e.z));
            var view = cam.worldToCameraMatrix * flip;
            mirror.worldToCameraMatrix = view;
            // Oblique near plane on the water (a hair above it): only what stands above the water is mirrored.
            Vector3 onPlane = view.MultiplyPoint(new Vector3(0, level + clipOffset, 0)), normal = view.MultiplyVector(Vector3.up).normalized;
            mirror.projectionMatrix = cam.CalculateObliqueMatrix(new Vector4(normal.x, normal.y, normal.z, -Vector3.Dot(onPlane, normal)));
            mirror.cullingMatrix = cam.projectionMatrix * view;   // cull against the plain mirrored frustum
            bool fog = RenderSettings.fog, invert = GL.invertCulling;
            float shadows = QualitySettings.shadowDistance; int lights = QualitySettings.pixelLightCount;
            rendering = true;
            try
            {
                RenderSettings.fog = false;                              // the water shader fogs the whole reflected path instead
                QualitySettings.shadowDistance = 0;                      // no second shadow map
                QualitySettings.pixelLightCount = Mathf.Min(lights, 2);
                GL.invertCulling = !invert;                              // a mirrored view turns every face inside out
                mirror.Render();
            }
            finally
            {
                GL.invertCulling = invert; RenderSettings.fog = fog;
                QualitySettings.shadowDistance = shadows; QualitySettings.pixelLightCount = lights;
                rendering = false;
            }
            Shader.SetGlobalTexture(TextureId, target);
            Shader.SetGlobalTexture(DepthId, target, RenderTextureSubElement.Depth);
            Shader.SetGlobalMatrix(InvProjId, GL.GetGPUProjectionMatrix(mirror.projectionMatrix, false).inverse);
            Shader.SetGlobalVector(ParamsId, new Vector4(level, 1, RenderSettings.reflectionIntensity, bend));
            Level = level;
            return true;
        }

        /// <summary>The reflection camera and texture: made on first use, the texture again when the view size changes.</summary>
        bool Prepare(Camera cam)
        {
            int vw = Mathf.Max(1, cam.pixelWidth), vh = Mathf.Max(1, cam.pixelHeight);
            int w = Mathf.Clamp(Mathf.RoundToInt(vw * scale), 64, Mathf.Max(64, maxWidth));
            int h = Mathf.Max(32, Mathf.RoundToInt(w * (float)vh / vw));
            if (target == null || target.width != w || target.height != h)
            {
                if (target != null) { target.Release(); Destroy(target); }
                target = new RenderTexture(w, h, 24, RenderTextureFormat.DefaultHDR, RenderTextureReadWrite.Linear)
                {
                    name = "Water reflection", useMipMap = true, autoGenerateMips = true, filterMode = FilterMode.Trilinear,
                    wrapMode = TextureWrapMode.Clamp, antiAliasing = 1
                };
                if (!target.Create()) { Destroy(target); target = null; return false; }
            }
            if (mirror == null)
            {
                var go = new GameObject("Water reflection camera"); go.transform.SetParent(transform, false);
                mirror = go.AddComponent<Camera>(); mirror.enabled = false;   // rendered by hand, never on its own
                mirror.renderingPath = RenderingPath.Forward; mirror.allowHDR = true; mirror.allowMSAA = false;
                mirror.useOcclusionCulling = false; mirror.depthTextureMode = DepthTextureMode.None;
            }
            mirror.targetTexture = target;
            return true;
        }
    }
}

