using System;
using System.Collections;
using System.IO;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using Crulanda.Encounter;
using Crulanda.World;

namespace Crulanda.Tests
{
    /// <summary>
    /// The water's planar reflection (WaterReflection) is wired up: every water surface is registered with it and kept out of
    /// its own reflection (the Water layer), and particles never reach the reflection camera (TransparentFX). Batch tests have
    /// no renderer, so how the reflection looks is checked in the capture tour.
    /// </summary>
    public class WaterReflectionTests
    {
        string root;
        void OnLoaded(Scene scene, LoadSceneMode mode) { var s = UnityEngine.Object.FindFirstObjectByType<EncounterSession>(); if (s != null) s.SaveDirectoryOverride = root; }
        [UnitySetUp] public IEnumerator Setup()
        {
            root = Path.Combine(Path.GetTempPath(), "Crulanda-reflection-" + Guid.NewGuid().ToString("N"));
            SceneManager.sceneLoaded += OnLoaded;
            yield return SceneManager.LoadSceneAsync("Oakhaven", LoadSceneMode.Single);
            for (int i = 0; i < 3; i++) yield return null;
        }
        [UnityTearDown] public IEnumerator Cleanup()
        {
            SceneManager.sceneLoaded -= OnLoaded;
            var empty = SceneManager.CreateScene("Empty-" + Guid.NewGuid().ToString("N")); SceneManager.SetActiveScene(empty);
            yield return SceneManager.UnloadSceneAsync("Oakhaven");
            if (Directory.Exists(root)) Directory.Delete(root, true);
        }

        [UnityTest] public IEnumerator Water_and_particles_stay_out_of_the_water_reflection()
        {
            var zone = ZoneBuilder.Active; Assert.IsNotNull(zone, "Oakhaven builds its zone.");
            var mirror = zone.GetComponent<WaterReflection>(); Assert.IsNotNull(mirror, "The zone mirrors its surroundings in its water.");
            int surfaces = 0;
            foreach (var r in zone.GetComponentsInChildren<MeshRenderer>(true))
            {
                if (r.sharedMaterial == null || r.sharedMaterial.shader == null || r.sharedMaterial.shader.name != "Crulanda/Water") continue;
                surfaces++;
                Assert.AreEqual(WaterReflection.WaterLayer, r.gameObject.layer, r.name + ": water surfaces sit on the Water layer (left out of their own reflection).");
            }
            Assert.Greater(surfaces, 0, "Oakhaven has water.");
            Assert.AreEqual(surfaces, mirror.Surfaces, "Every water surface is registered with the reflection.");
            foreach (var ps in zone.GetComponentsInChildren<ParticleSystem>(true))
                Assert.AreEqual(WaterReflection.NoReflectLayer, ps.gameObject.layer, ps.name + ": particles are not mirrored in the water.");
            yield return null;
        }
    }
}
#endif

