sampler2D _Wavelets;
float4 _Absorb;
float _WaveletScale, _Glint, _GlintSharp, _Streaks;
// One octave of wavelets carried by a two-phase flow map. p: metres; flow: m/s; stretch: squash along the current;
// tiles: tiles per metre; rot: the octave's turn; ph0: this pixel's phase (0..1, one cycle = 3.33 s). The two
// phases run half a cycle apart and jump apart in the texture, so they never show the same ripples; each fades out
// as it resets, and the blend keeps the ripple strength steady. Returns the slope in the surface's tangent frame.
float2 WaveletSlope(float2 p, float2 flow, float2 stretch, float tiles, float2x2 rot, float ph0)
{
    const float cycle = 3.333;
    float ph1 = frac(ph0 + 0.5);
    float w0 = 1 - abs(1 - 2 * ph0), w1 = 1 - w0;
    float2 uv0 = mul(rot, (p - flow * (ph0 * cycle)) * stretch) * tiles;
    float2 uv1 = mul(rot, (p - flow * (ph1 * cycle)) * stretch) * tiles + float2(0.37, 0.61);
    float2 s = (UnpackNormal(tex2D(_Wavelets, uv0)).xy * w0 + UnpackNormal(tex2D(_Wavelets, uv1)).xy * w1) * rsqrt(w0 * w0 + w1 * w1);
    return mul(s, rot) * stretch;
}
