/// with log-spaced wavelengths (whole periods per tile, so it repeats seamlessly), taller as they get longer, so no
/// single wavelength or direction shows. Slopes are scaled to a fixed RMS so the shader's strengths hold whatever the
/// draw. Fixed seed: the same texture every build.
/// </summary>
static Texture2D WaveletTex(string name, int size)
{
    string path = ArtRoot + "/" + name + ".png";
    if (!File.Exists(path))
    {
